<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/espocrm/bootstrap.php';
use Espo\Core\{Application,AclManager,InjectableFactory};
use Espo\Core\ORM\EntityManager;
use Espo\Core\Tenant\{TenantContext,TenantContextStore};
use Espo\Core\Exceptions\{BadRequest,Conflict,Forbidden,NotFound};
use Espo\Custom\Tools\Conversation\{ChatStore,MessagingConnectionService,TwilioMessagingLookup};
use Espo\Custom\Tools\Auth\ProviderSecretCipher;

$envNames=['NEXA_SECRET_ACTIVE_KEY_ID','NEXA_SECRET_KEYS'];$oldEnv=[];
foreach($envNames as $name)$oldEnv[$name]=getenv($name);
putenv('NEXA_SECRET_ACTIVE_KEY_ID=messaging-fixture');putenv('NEXA_SECRET_KEYS='.json_encode(['messaging-fixture'=>base64_encode(random_bytes(32))]));
$app=new Application();$app->setupSystemUser();$c=$app->getContainer();
$em=$c->getByClass(EntityManager::class);$factory=$c->getByClass(InjectableFactory::class);$contexts=$c->getByClass(TenantContextStore::class);
$a=new TenantContext('30000000-0000-4000-8000-000000000001','isolation-alpha','messaging-test');
$b=new TenantContext('30000000-0000-4000-8000-000000000002','isolation-beta','messaging-test');
$call=fn($fn)=>$contexts->runWith($a,$fn);$other=fn($fn)=>$contexts->runWith($b,$fn);$checks=0;
$assert=function(bool $ok,string $why)use(&$checks):void{$checks++;if(!$ok)throw new RuntimeException($why);};
$deny=function(callable $fn,string $why)use($assert):void{try{$fn();}catch(BadRequest|Conflict|Forbidden|NotFound $e){$assert(true,$why);return;}$assert(false,$why);};
$tx=$em->getTransactionManager();$tx->start();
try {
    $suffix=bin2hex(random_bytes(5));$store=$factory->create(ChatStore::class);$cipher=$factory->create(ProviderSecretCipher::class);
    $make=fn($ctx,$type)=>$contexts->runWith($ctx,fn()=>$em->createEntity('User',['userName'=>'msg-'.$type.'-'.$ctx->slug.'-'.$suffix,'emailAddress'=>'msg-'.$type.'-'.$ctx->slug.'-'.$suffix.'@example.test','lastName'=>'Messaging fixture','type'=>$type,'isActive'=>true]));
    $admin=$make($a,'admin');$foreign=$make($b,'admin');$staff=$make($a,'regular');
    $reload=fn($ctx,$u)=>$contexts->runWith($ctx,fn()=>$em->getEntityById('User',$u->getId()));
    $admin=$reload($a,$admin);$foreign=$reload($b,$foreign);$staff=$reload($a,$staff);
    $build=fn($u,$lookup=null)=>$factory->createWith(MessagingConnectionService::class,['user'=>$u,'acl'=>$c->getByClass(AclManager::class)->createUserAcl($u)]+($lookup?['lookup'=>$lookup]:[]));
    $service=$build($admin);$beta=$build($foreign);$regular=$build($staff);
    $secret=bin2hex(random_bytes(16));$account='AC'.bin2hex(random_bytes(16));
    $input=(object)['op'=>'save','name'=>'SMS fixture','accountSid'=>$account,'channel'=>'sms','sender'=>'+14155550100','secret'=>$secret,'disabled'=>false];
    $saved=$call(fn()=>$service->process($input));$id=$saved['id'];
    $assert($saved['status']==='unverified','Saved credentials do not activate sending.');
    $row=$call(fn()=>$store->rows('SELECT * FROM nexa_messaging_connection WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$id]))[0];
    $assert($row['secret_encrypted']!==$secret&&!str_contains($row['secret_encrypted'],$secret),'Provider token is encrypted at rest.');
    $assert($cipher->decryptFor($row['secret_encrypted'],$a->tenantId,$a->serviceId,'messaging:'.$id)===$secret,'Stored secret decrypts only with the correct binding.');
    foreach([[$b->tenantId,$a->serviceId,'messaging:'.$id],[$a->tenantId,ChatStore::uuid(),'messaging:'.$id],[$a->tenantId,$a->serviceId,'messaging:wrong']] as [$tenant,$scope,$purpose]) {
        $blocked=false;try{$cipher->decryptFor($row['secret_encrypted'],$tenant,$scope,$purpose);}catch(RuntimeException $error){$blocked=true;}$assert($blocked,'Ciphertext cannot be rebound to another tenant or connection.');
    }
    $json=json_encode($call(fn()=>$service->process((object)['op'=>'list'])));
    $assert(!str_contains($json,$secret)&&!str_contains($json,'secret_encrypted'),'Browser responses contain neither secret nor ciphertext.');
    $assert($other(fn()=>$beta->process((object)['op'=>'list']))['list']===[],'Other tenants cannot list the connection.');
    $otherService=new TenantContext($a->tenantId,$a->slug,'messaging-test','',ChatStore::uuid());
    $deny(fn()=>$contexts->runWith($otherService,fn()=>$service->process((object)['op'=>'list'])),'The same tenant cannot reuse an administrator from another service context.');
    $deny(fn()=>$call(fn()=>$regular->process((object)['op'=>'list'])),'Non-admins cannot inspect provider configuration.');
    $update=clone $input;unset($update->secret);$update->id=$id;$update->version=1;$update->name='Renamed connection';
    $otherSave=$other(fn()=>$beta->process($input));$assert($otherSave['id']!==$id,'Unverified configurations do not squat another tenant sender.');
    $deny(fn()=>$other(fn()=>$beta->process($update)),'Another tenant cannot update a known connection ID.');
    $call(fn()=>$service->process($update));
    $preserved=$call(fn()=>$store->rows('SELECT secret_encrypted FROM nexa_messaging_connection WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$id]))[0];
    $assert($preserved['secret_encrypted']===$row['secret_encrypted'],'Omitting a secret preserves its ciphertext.');
    $deny(fn()=>$call(fn()=>$service->process($update)),'Stale connection edits fail.');
    $bad=clone $update;$bad->version=2;$bad->sender='+14155550199';$deny(fn()=>$call(fn()=>$service->process($bad)),'Provider identity cannot be silently reassigned.');
    $bad=clone $update;$bad->version=2;$bad->status='active';$deny(fn()=>$call(fn()=>$service->process($bad)),'Client cannot activate sending through an extra setting.');
    $contact=$call(fn()=>$em->createEntity('Contact',['firstName'=>'Held','lastName'=>'Recipient','phoneNumber'=>'+14155550101']));
    $foreignContact=$other(fn()=>$em->createEntity('Contact',['firstName'=>'Foreign','lastName'=>'Recipient','phoneNumber'=>'+14155550102']));
    $nonce=ChatStore::uuid();$held=$call(fn()=>$service->stage($id,$contact->getId(),'Never dispatched fixture',$nonce));
    $again=$call(fn()=>$service->stage($id,$contact->getId(),'Never dispatched fixture',$nonce));
    $assert($held['status']==='held'&&$again['id']===$held['id']&&$again['duplicate'],'Internal staging is durable and idempotent without dispatching.');
    $deny(fn()=>$call(fn()=>$service->stage($id,$contact->getId(),'Changed intent',$nonce)),'A request key cannot become a different send.');
    $deny(fn()=>$call(fn()=>$service->stage($id,$foreignContact->getId(),'Cross tenant',ChatStore::uuid())),'A foreign Contact cannot be staged.');
    $contact->set(['doNotContact'=>true,'doNotContactChannels'=>'sms']);$call(fn()=>$em->saveEntity($contact));
    $deny(fn()=>$call(fn()=>$service->stage($id,$contact->getId(),'Suppressed',ChatStore::uuid())),'Channel suppression is checked even for held staging.');
    $update->version=2;$update->disabled=true;$call(fn()=>$service->process($update));
    $deny(fn()=>$call(fn()=>$service->stage($id,$contact->getId(),'Disabled',ChatStore::uuid())),'Disabled connections cannot stage new requests.');
    $outbox=$call(fn()=>$store->rows('SELECT recipient,connection_version,created_by_id FROM nexa_messaging_outbox WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$held['id']]))[0];
    $assert($outbox['recipient']==='+14155550101'&&(int)$outbox['connection_version']===2&&$outbox['created_by_id']===$admin->getId(),'Staging records the authoritative recipient, connection revision and actor.');
    $audits=json_encode($call(fn()=>$store->rows("SELECT metadata_json FROM nexa_audit_event WHERE tenant_id=? AND service_id=? AND subject_id=?",[$a->tenantId,$a->serviceId,$id])));
    $assert(!str_contains($audits,$secret)&&!str_contains($audits,$row['secret_encrypted']),'Audit records contain no provider secrets.');
    $lookup=new class extends TwilioMessagingLookup {
        public $during=null;public int $calls=0;public bool $failure=false;
        public function proveSms(string $account,string $secret,string $sender):array{$this->calls++;if($this->during)($this->during)();if($this->failure)throw new Forbidden('Fixture provider rejected ownership.');return ['phoneSid'=>'PN'.str_repeat('1',32)];}
        public function proveWhatsApp(string $account,string $secret,string $sender,string $sid):array{$this->calls++;return ['phoneSid'=>$sid];}
    };
    $verifier=$build($admin,$lookup);
    $deny(fn()=>$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$id,'version'=>3])),'Disabled connections cannot contact the verification provider.');
    $assert($lookup->calls===0,'Disabled verification fails before provider I/O.');
    $update->version=3;$update->disabled=false;$call(fn()=>$service->process($update));
    $verified=$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$id,'version'=>4]));
    $assert($verified['status']==='verified'&&$verified['dispatchEnabled']===false,'Provider proof verifies ownership but does not enable dispatch.');
    $proof=$call(fn()=>$store->rows('SELECT verified_at,provider_resource_sid FROM nexa_messaging_connection WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$id]))[0];
    $assert($proof['verified_at']!==null&&$proof['provider_resource_sid']==='PN'.str_repeat('1',32),'Accepted provider evidence is persisted with its UTC check time.');
    $heldState=$call(fn()=>$store->rows('SELECT status FROM nexa_messaging_outbox WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$held['id']]))[0];
    $assert($heldState['status']==='held','Verification never releases previously staged messages.');
    $betaVerifier=$build($foreign,$lookup);
    $deny(fn()=>$other(fn()=>$betaVerifier->process((object)['op'=>'verify','id'=>$otherSave['id'],'version'=>1])),'Only one tenant can hold verified ownership of a sender.');
    $assert($other(fn()=>$beta->process((object)['op'=>'list']))['list'][0]['status']==='unverified','A conflicting proof does not partially activate another tenant.');
    $deny(fn()=>$other(fn()=>$betaVerifier->process((object)['op'=>'verify','id'=>$id,'version'=>5])),'A foreign tenant cannot verify a known connection ID.');
    $update->version=5;$update->name='Verified rename';$renamed=$call(fn()=>$service->process($update));
    $assert($renamed['status']==='verified','A name-only edit preserves unchanged provider proof.');
    $rotate=clone $update;$rotate->version=6;$rotate->secret=bin2hex(random_bytes(16));$rotated=$call(fn()=>$service->process($rotate));
    $assert($rotated['status']==='unverified','Rotating a token invalidates the previous ownership proof.');
    $lookup->during=fn()=>$call(fn()=>$store->execute('UPDATE nexa_messaging_connection SET version_number=version_number+1 WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$id]));
    $deny(fn()=>$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$id,'version'=>7])),'A configuration edit during provider I/O invalidates the proof.');
    $lookup->during=null;
    $assert($call(fn()=>$service->process((object)['op'=>'list']))['list'][0]['status']==='unverified','A raced proof cannot overwrite the newer configuration.');
    $whatsapp=clone $input;$whatsapp->channel='whatsapp';$whatsapp->sender='whatsapp:'.$input->sender;
    $wa=$call(fn()=>$service->process($whatsapp));
    $deny(fn()=>$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$wa['id'],'version'=>1])),'SMS number proof is never applied to WhatsApp.');
    $waVerified=$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$wa['id'],'version'=>1,'senderSid'=>'XE'.str_repeat('2',32)]));
    $assert($waVerified['status']==='verified'&&!$waVerified['dispatchEnabled'],'Approved WhatsApp proof is stored without activating dispatch.');
    $waProof=$call(fn()=>$store->rows('SELECT provider_resource_sid,dispatch_enabled FROM nexa_messaging_connection WHERE tenant_id=? AND service_id=? AND id=?',[...$store->scope(),$wa['id']]))[0];
    $assert($waProof['provider_resource_sid']==='XE'.str_repeat('2',32)&&!(bool)$waProof['dispatch_enabled'],'WhatsApp sender proof remains distinct from SMS PN proof.');
    $templates=new class extends \Espo\Custom\Tools\Conversation\WhatsAppTemplateLookup {public $during=null;public function inspect(string $account,string $secret,string $sid):array{if($this->during)($this->during)();return ['contentSid'=>$sid,'name'=>'fixture_approved','language'=>'en','category'=>'UTILITY','body'=>'Hello {{1}}','variableKeys'=>['1']];}};
    $waService=$factory->createWith(MessagingConnectionService::class,['user'=>$admin,'acl'=>$c->getByClass(AclManager::class)->createUserAcl($admin),'lookup'=>$lookup,'templates'=>$templates]);
    $inspect=(object)['op'=>'inspectWhatsAppTemplate','id'=>$wa['id'],'version'=>2,'contentSid'=>'HX'.str_repeat('3',32)];
    $assert($call(fn()=>$waService->process($inspect))['name']==='fixture_approved','Tenant administrator can inspect approval through the connected WhatsApp account.');
    $deny(fn()=>$other(fn()=>$beta->process($inspect)),'Foreign tenant cannot inspect a known WhatsApp template connection.');
    $deny(fn()=>$call(fn()=>$regular->process($inspect)),'Ordinary staff cannot use provider credentials for template inspection.');
    $templates->during=fn()=>$call(fn()=>$store->execute('UPDATE nexa_messaging_connection SET version_number=version_number+1 WHERE tenant_id=? AND service_id=? AND id=?',[...$store->scope(),$wa['id']]));
    $deny(fn()=>$call(fn()=>$waService->process($inspect)),'Connection changes during template I/O invalidate the inspection result.');
    $deny(fn()=>$call(fn()=>$waService->process((object)['op'=>'activate','id'=>$wa['id'],'version'=>3,'enabled'=>true])),'SMS activation cannot enable WhatsApp sending.');
    $call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$id,'version'=>8]));
    $lookup->failure=true;
    $deny(fn()=>$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$id,'version'=>9])),'A definitive provider rejection revokes a previous successful proof.');
    $revoked=$call(fn()=>$store->rows('SELECT status,verified_at,provider_resource_sid FROM nexa_messaging_connection WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$id]))[0];
    $assert($revoked['status']==='unverified'&&$revoked['verified_at']===null&&$revoked['provider_resource_sid']===null,'Rejected ownership no longer appears verified.');
    $lookup->failure=false;
    $lookup->during=fn()=>$call(fn()=>$store->execute('UPDATE user SET is_active=0 WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$admin->getId()]));
    $deny(fn()=>$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$id,'version'=>10])),'Administrator deactivation during provider I/O cannot authorize proof acceptance.');
    $call(fn()=>$store->execute('UPDATE user SET is_active=1 WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$admin->getId()]));
    $unchanged=$call(fn()=>$store->rows('SELECT status FROM nexa_messaging_connection WHERE tenant_id=? AND service_id=? AND id=?',[$a->tenantId,$a->serviceId,$id]))[0];
    $assert($unchanged['status']==='unverified','A deactivated actor does not leave a partially verified sender.');
    $lookup->during=fn()=>$call(fn()=>$store->execute("UPDATE nexa_tenant SET status='suspended' WHERE id=?",[$a->tenantId]));
    $deny(fn()=>$call(fn()=>$verifier->process((object)['op'=>'verify','id'=>$id,'version'=>10])),'Suspending a tenant during provider I/O prevents proof acceptance.');
    $deny(fn()=>$call(fn()=>$service->process((object)['op'=>'list'])),'Suspended tenants cannot inspect connection settings through direct service calls.');
    $call(fn()=>$store->execute("UPDATE nexa_tenant SET status='active' WHERE id=?",[$a->tenantId]));
    $lookup->during=null;
    echo "Messaging connection checks passed: $checks (rollback-only; fake verification, no delivery).\n";
}catch(Throwable $error){fwrite(STDERR,get_class($error).': '.$error->getMessage()."\n".$error->getTraceAsString()."\n");throw $error;}
finally {if($tx->isStarted())$tx->rollback();foreach($oldEnv as $name=>$value)putenv($value===false?$name:$name.'='.$value);}
